async function POST2(req, { params }) {
  try {
    const session = await getSessionFromRequest(req);
    if (!session) {
      return import_server2.NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
    const dbUser = await prisma.user.findUnique({ where: { id: session.id } });
    if (!dbUser) {
      return import_server2.NextResponse.json({ error: "User not found" }, { status: 401 });
    }
    if (dbUser.isBanned) {
      return import_server2.NextResponse.json({ error: "Your account has been banned. Please contact support." }, { status: 403 });
    }
    const resolvedParams = await params;
    const { id: productId } = resolvedParams;
    const { latitude, longitude } = await req.json();
    const transactionResult = await prisma.$transaction(async (tx) => {
      const product = await tx.product.findUnique({
        where: { id: productId },
        include: {
          scans: {
            orderBy: { scannedAt: "asc" }
          }
        }
      });
      if (!product) {
        throw new Error("PRODUCT_NOT_FOUND");
      }
      const isFirstScan = product.scans.length === 0;
      const scan = await tx.scanHistory.create({
        data: {
          productId,
          userId: session.id,
          latitude,
          longitude,
          isFirstScan
        }
      });
      if (isFirstScan) {
        await tx.user.update({
          where: { id: session.id },
          data: {
            creditPoints: {
              increment: product.creditPoints
            }
          }
        });
      }
      return { scan, isFirstScan };
    });
    const updatedProduct = await prisma.product.findUnique({
      where: { id: productId },
      include: {
        scans: {
          orderBy: { scannedAt: "asc" }
        }
      }
    });
    return import_server2.NextResponse.json({ product: updatedProduct, scan: transactionResult.scan, isFirstScan: transactionResult.isFirstScan });
  } catch (error) {
    if (error.message === "PRODUCT_NOT_FOUND") {
      return import_server2.NextResponse.json({ error: "Product not found" }, { status: 404 });
    }
    console.error("Scan error:", error);
    return import_server2.NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

